"use strict";(globalThis.webpackChunkbook=globalThis.webpackChunkbook||[]).push([[142],{2512:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/book-writing/ur/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Module 1: The Robotic Nervous System \u2013 ROS 2","items":[{"type":"link","href":"/book-writing/ur/docs/ros-2/concepts","label":"Chapter 1.1: Introduction to ROS 2 Concepts","docId":"ros-2/concepts","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/ros-2/urdf","label":"Chapter 1.2: Creating a Humanoid Description (URDF)","docId":"ros-2/urdf","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/ros-2/rclpy","label":"Chapter 1.3: The Python Bridge: rclpy for AI Agents","docId":"ros-2/rclpy","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 2: The Digital Twin \u2013 Gazebo & Unity","items":[{"type":"link","href":"/book-writing/ur/docs/simulation/physics","label":"Chapter 2.1: Fundamentals of Physics Simulation","docId":"simulation/physics","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/simulation/environment","label":"Chapter 2.2: Designing a Digital Environment","docId":"simulation/environment","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/simulation/sensors","label":"Chapter 2.3: Simulating Sensors (LiDAR, Camera, IMU)","docId":"simulation/sensors","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 3: The AI-Robot Brain \u2013 NVIDIA Isaac","items":[{"type":"link","href":"/book-writing/ur/docs/nvidia-isaac/isaac-sim","label":"Chapter 3.1: Photorealistic Training with Isaac Sim","docId":"nvidia-isaac/isaac-sim","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/nvidia-isaac/isaac-ros","label":"Chapter 3.2: Accelerated Perception with Isaac ROS","docId":"nvidia-isaac/isaac-ros","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/nvidia-isaac/navigation","label":"Chapter 3.3: Navigation and Mapping (VSLAM, Nav2)","docId":"nvidia-isaac/navigation","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/nvidia-isaac/reinforcement-learning","label":"Chapter 3.4: Introduction to Reinforcement Learning for Robotics","docId":"nvidia-isaac/reinforcement-learning","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 4: Vision-Language-Action (VLA)","items":[{"type":"link","href":"/book-writing/ur/docs/vla/whisper","label":"Chapter 4.1: Voice to Text with Whisper","docId":"vla/whisper","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/vla/llm-planning","label":"Chapter 4.2: Planning and Reasoning with LLMs","docId":"vla/llm-planning","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/vla/vision-models","label":"Chapter 4.3: Object Recognition with Vision Models","docId":"vla/vision-models","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/vla/action-execution","label":"Chapter 4.4: Executing Actions in ROS 2","docId":"vla/action-execution","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 5: Capstone","items":[{"type":"link","href":"/book-writing/ur/docs/capstone/overview","label":"Chapter 5.1: Project Overview and Setup","docId":"capstone/overview","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/capstone/integration","label":"Chapter 5.2: Integrating the Full Pipeline","docId":"capstone/integration","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/capstone/sim-to-real","label":"Chapter 5.3: Sim-to-Real Transfer and Deployment","docId":"capstone/sim-to-real","unlisted":false},{"type":"link","href":"/book-writing/ur/docs/capstone/demonstration","label":"Chapter 5.4: Final Demonstration and Evaluation","docId":"capstone/demonstration","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"capstone/demonstration":{"id":"capstone/demonstration","title":"Chapter 5.4: Final Demonstration and Evaluation","description":"We have arrived at the final chapter of our journey. We have designed, simulated, and deployed a complex, AI-driven robotics system. The final step is to demonstrate its capabilities, evaluate its performance, and reflect on the path forward.","sidebar":"tutorialSidebar"},"capstone/integration":{"id":"capstone/integration","title":"Chapter 5.2: Integrating the Full Pipeline","description":"This chapter is the heart of the capstone project. Here, we will write the code for the four custom ROS 2 nodes that make up our VLA pipeline and create the main launch file to run the entire system. The conceptual outlines from Module 4 will now be turned into a functional, integrated application.","sidebar":"tutorialSidebar"},"capstone/overview":{"id":"capstone/overview","title":"Chapter 5.1: Project Overview and Setup","description":"Welcome to the final module. Over the past four modules, we have explored the foundational technologies required to build an intelligent robot:","sidebar":"tutorialSidebar"},"capstone/sim-to-real":{"id":"capstone/sim-to-real","title":"Chapter 5.3: Sim-to-Real Transfer and Deployment","description":"The ultimate goal of simulation is to develop software that works on a physical robot. The process of moving from a simulated environment to the real world is known as Sim-to-Real Transfer. This is a notoriously challenging step in robotics, often referred to as crossing the \\"reality gap.\\"","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction","description":"Welcome to the book on Physical AI & Humanoid Robotics.","sidebar":"tutorialSidebar"},"nvidia-isaac/isaac-ros":{"id":"nvidia-isaac/isaac-ros","title":"Chapter 3.2: Accelerated Perception with Isaac ROS","description":"While Isaac Sim provides the training ground, Isaac ROS provides the high-speed tools for a robot to perceive the world in real-time. Isaac ROS is a collection of hardware-accelerated packages for perception, specifically designed to leverage the power of NVIDIA GPUs and Jetson platforms.","sidebar":"tutorialSidebar"},"nvidia-isaac/isaac-sim":{"id":"nvidia-isaac/isaac-sim","title":"Chapter 3.1: Photorealistic Training with Isaac Sim","description":"While Gazebo is a powerful and versatile physics simulator, the world of robotics AI, especially in vision-based tasks, is increasingly dominated by the need for high-fidelity, photorealistic simulation. NVIDIA\'s Isaac Sim is a robotics simulation platform built on NVIDIA Omniverse\u2122. It leverages the full power of NVIDIA\'s RTX GPUs to create physically accurate and visually stunning simulations, making it an ideal environment for training and testing modern AI perception models.","sidebar":"tutorialSidebar"},"nvidia-isaac/navigation":{"id":"nvidia-isaac/navigation","title":"Chapter 3.3: Navigation and Mapping (VSLAM, Nav2)","description":"Once a robot can perceive its environment, the next logical step is to move through it safely and purposefully. This is the domain of navigation. Modern robot navigation is a complex interplay of three core components: mapping, localization, and planning.","sidebar":"tutorialSidebar"},"nvidia-isaac/reinforcement-learning":{"id":"nvidia-isaac/reinforcement-learning","title":"Chapter 3.4: Introduction to Reinforcement Learning for Robotics","description":"While classical navigation techniques like Nav2 are powerful for point-to-point travel, Reinforcement Learning (RL) opens up a new frontier of learned behaviors. Instead of programming a robot\'s actions explicitly, RL allows a robot to learn complex behaviors through trial and error, guided by a system of rewards and penalties.","sidebar":"tutorialSidebar"},"ros-2/concepts":{"id":"ros-2/concepts","title":"Chapter 1.1: Introduction to ROS 2 Concepts","description":"Welcome to the foundational chapter of our journey into robotics. Before we can make our robot see, think, or act, we need to build its nervous system. In modern robotics, that nervous system is the Robot Operating System (ROS). This chapter introduces the core concepts of ROS 2, the second generation of ROS, which provides the communication backbone for all other components we will build.","sidebar":"tutorialSidebar"},"ros-2/rclpy":{"id":"ros-2/rclpy","title":"Chapter 1.3: The Python Bridge: rclpy for AI Agents","description":"While ROS 2 is built on a C++ core for performance, its real power for AI development comes from its Python client library, rclpy. This library allows us to write full-fledged ROS 2 nodes in Python, giving us access to the vast ecosystem of Python libraries for machine learning, computer vision, and language processing (e.g., TensorFlow, PyTorch, OpenCV, Hugging Face).","sidebar":"tutorialSidebar"},"ros-2/urdf":{"id":"ros-2/urdf","title":"Chapter 1.2: Creating a Humanoid Description (URDF)","description":"To interact with a robot in simulation or visualize it in a robot\'s operating environment, we need a standardized way to describe its physical characteristics. The Unified Robot Description Format (URDF) is an XML-based file format used in ROS to describe all aspects of a robot, including its kinematic and dynamic properties, visual appearance, and collision models.","sidebar":"tutorialSidebar"},"simulation/environment":{"id":"simulation/environment","title":"Chapter 2.2: Designing a Digital Environment","description":"A robot\'s behavior is deeply influenced by its environment. A cluttered apartment, a structured warehouse, or an outdoor campus all present unique challenges. To effectively test our robot, we need to create digital environments that replicate the key features of its intended operating domain.","sidebar":"tutorialSidebar"},"simulation/physics":{"id":"simulation/physics","title":"Chapter 2.1: Fundamentals of Physics Simulation","description":"With a structural description (URDF) and a communication framework (ROS 2) in place, the next step is to create a world for our robot to live in. A physics simulator allows us to model our robot and its environment, letting us test algorithms safely and rapidly without needing physical hardware for every iteration.","sidebar":"tutorialSidebar"},"simulation/sensors":{"id":"simulation/sensors","title":"Chapter 2.3: Simulating Sensors (LiDAR, Camera, IMU)","description":"A robot operating in the dark is useless. To perform any intelligent task, a robot must be able to perceive its environment. In simulation, this is achieved by adding sensor plugins to our robot model. These plugins generate realistic data that mimics the output of their real-world hardware counterparts.","sidebar":"tutorialSidebar"},"vla/action-execution":{"id":"vla/action-execution","title":"Chapter 4.4: Executing Actions in ROS 2","description":"We have now converted a voice command to text, used an LLM to create a plan, and used a VLM to find the object required by that plan. The final piece of the puzzle is to translate the plan\'s abstract steps\u2014like goto(location=\'table\') or pickup(object_id=123)\u2014into actual robot movements.","sidebar":"tutorialSidebar"},"vla/llm-planning":{"id":"vla/llm-planning","title":"Chapter 4.2: Planning and Reasoning with LLMs","description":"Once we have a text command from Whisper, such as \\"bring me the red block from the table,\\" the robot needs to understand the intent behind the words and translate it into a sequence of concrete actions. This is where Large Language Models (LLMs) like GPT, Llama, or Gemini come in.","sidebar":"tutorialSidebar"},"vla/vision-models":{"id":"vla/vision-models","title":"Chapter 4.3: Object Recognition with Vision Models","description":"The LLM has given our robot a plan, for example: findobject(objectname=\'apple\', color=\'green\'). Now, the robot needs to execute this step. To do this, it must visually search its environment and identify the correct object. This is the task of object recognition.","sidebar":"tutorialSidebar"},"vla/whisper":{"id":"vla/whisper","title":"Chapter 4.1: Voice to Text with Whisper","description":"The ultimate goal of robotics is to create machines that can collaborate with humans naturally. The most natural human interface is language. To build a robot that can understand spoken commands, the first step is to convert the sound of a human voice into written text. This process is called Automatic Speech Recognition (ASR).","sidebar":"tutorialSidebar"}}}}')}}]);